cssCode:
.crown-wrap {
  position: relative; display: flex; align-items: center; justify-content: center;
  width: 150px; height: 150px;
}
.crown-svg {
  width: 100px; height: 100px; z-index: 5;
  filter: drop-shadow(0 0 20px rgba(255, 0, 127, 0.8));
  animation: crownFloat 3s ease-in-out infinite alternate;
}
.crown-path {
  fill: rgba(255, 0, 127, 0.2); stroke: #ff007f; stroke-width: 3;
  stroke-dasharray: 400; stroke-dashoffset: 400;
  animation: drawCrown 2s ease-in-out forwards;
}
.sparkle-dot {
  position: absolute; width: 6px; height: 6px; background: #ff007f;
  border-radius: 50%; box-shadow: 0 0 10px #ff007f;
  animation: popSparkle 1.5s infinite ease-out; opacity: 0;
}
@keyframes drawCrown { to { stroke-dashoffset: 0; } }
@keyframes crownFloat { 0% { transform: scale(1); } 100% { transform: scale(1.1); } }
@keyframes popSparkle {
  0% { transform: translateY(0) scale(1); opacity: 1; }
  100% { transform: translateY(-50px) scale(0); opacity: 0; }
}

