const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

c.innerHTML = `
  <div class="crown-wrap" id="crown-wrap">
    <svg class="crown-svg" viewBox="0 0 100 100">
      <path class="crown-path" d="M10 80 L20 30 L40 50 L50 20 L60 50 L80 30 L90 80 Z" />
      <line x1="15" y1="90" x2="85" y2="90" class="crown-path" />
    </svg>
  </div>
`;

const wrap = document.getElementById('crown-wrap');
for (let i = 0; i < 5; i++) {
  const s = document.createElement('div');
  s.className = 'sparkle-dot';
  s.style.left = `${20 + Math.random() * 60}%`;
  s.style.animationDelay = `${Math.random() * 1.5}s`;
  wrap.appendChild(s);
}
